const IDENTITY_TYPES = ['inscriptionId', 'output', 'assetId', 'satpoint'];
const PROTOCOLS = ['ordinals', 'runes', 'stamps', 'counterparty', 'multi'];
const STATUSES = [
    'DRAFT',
    'CREATOR_SIGNED',
    'ANCHOR_PENDING',
    'ANCHORED',
    'SUPERSEDED',
    'REVOKED',
    'SIGNATURE_INVALID',
    'MEMBERSHIP_INVALID',
    'ANCHOR_CONFLICTED',
