        const value = parseSats(input && input.valueSats);
        if (value === null)
            return refuse('MALFORMED_SIGNED_RESULT', 'Every input needs an exact decimal value.');
        totalIn += value;
    }
    for (const output of resultOutputs) {
        const value = parseSats(output && output.valueSats);
        if (value === null)
            return refuse('MALFORMED_SIGNED_RESULT', 'Every output needs an exact decimal value.');
        totalOut += value;
