            return refuse('INPUT_REORDERED', `Input ${i} was reordered or substituted.`);
        }
        if (parseSats(actual?.valueSats) !== parseSats(expected?.valueSats)) {
            return refuse('VALUE_CHANGED', `Input ${i} no longer carries its presented value.`);
        }
