    };
    for (const give of i.gives) {
        const key = `${String(give.outpoint?.txid)}:${String(give.outpoint?.vout)}`;
        const error = checkAsset(give.assetType, (give.assetId || 'BTC'), inputByOutpoint.get(key)?.index, 'MAKER_ASSET');
        if (error)
            return error;
    }
    for (let n = 0; n < inputs.length; n += 1) {
        const input = inputs[n];
        if (input?.party !== 'taker')
            continue;
        for (const carried of Array.isArray(input.assets) ? input.assets : []) {
            const error = checkAsset(carried.assetType, (carried.assetId || 'BTC'), n, 'TAKER_ASSET');
            if (error)
                return error;
        }
    }
    return { ok: true };
}

